text:
{
  "kcs": [
    {
      "canonical_name": "数列极限",
      "aliases": ["数列收敛"],
      "description": "数列当n趋于无穷时趋近于某一常数的概念，用ε-N语言定义。"
    },
    {
      "canonical_name": "函数极限",
      "aliases": ["函数极限ε-δ定义"],
      "description": "函数在某点极限的概念，用ε-δ语言定义，包括左右极限。"
    },
    {
      "canonical_name": "两个重要极限",
      "aliases": ["重要极限", "第一个重要极限", "第二个重要极限"],
      "description": "两个在极限计算中常用的极限：lim sinx/x=1和lim(1+1/x)^x=e。"
    },
    {
      "canonical_name": "无穷小量",
      "aliases": ["无穷小"],
      "description": "极限为零的变量，包括比较和等价无穷小替换。"
    },
    {
      "canonical_name": "函数的连续性",
      "aliases": ["连续函数", "连续性"],
      "description": "函数在某点极限等于函数值的性质，刻画函数不间断。"
    },
    {
      "canonical_name": "导数",
      "aliases": ["导数定义", "微分", "导函数"],
      "description": "函数变化率的极限定义，几何意义为切线斜率。"
    },
    {
      "canonical_name": "基本初等函数导数表",
      "aliases": ["导数表", "求导公式"],
      "description": "常见初等函数（幂、指、对、三角等）的导数公式汇总。"
    },
    {
      "canonical_name": "求导法则",
      "aliases": ["四则求导法则", "复合函数求导", "反函数求导", "链式法则"],
      "description": "导数的四则运算、复合函数链式法则及反函数求导规则。"
    },
    {
      "canonical_name": "高阶导数",
      "aliases": ["高阶导"],
      "description": "二阶及以上导数，表示变化率的变化率，包括莱布尼茨公式。"
    },
    {
      "canonical_name": "隐函数求导",
      "aliases": ["隐函数微分法"],
      "description": "对隐式方程两边求导解出y'的方法。"
    },
    {
      "canonical_name": "罗尔定理",
      "aliases": ["Rolle定理"],
      "description": "若函数在闭区间连续、开区间可导且端点值相等，则存在内部点导数为零。"
    },
    {
      "canonical_name": "拉格朗日中值定理",
      "aliases": ["拉格朗日定理", "Lagrange中值定理"],
      "description": "存在一点使导数等于区间平均变化率，是罗尔定理的推广。"
    },
    {
      "canonical_name": "柯西中值定理",
      "aliases": ["Cauchy中值定理"],
      "description": "两个函数在区间上满足条件，存在一点使函数值差比等于导数比。"
    },
    {
      "canonical_name": "洛必达法则",
      "aliases": ["L'Hôpital法则"],
      "description": "用于计算0/0或∞/∞型未定式极限，分子分母分别求导再求极限。"
    },
    {
      "canonical_name": "泰勒公式",
      "aliases": ["Taylor公式", "泰勒展开", "Taylor展开"],
      "description": "用多项式逼近可微函数，含佩亚诺余项或拉格朗日余项。"
    },
    {
      "canonical_name": "不定积分",
      "aliases": ["原函数", "反导数"],
      "description": "导数的逆运算，全体原函数的集合，带有积分常数C。"
    },
    {
      "canonical_name": "换元积分法",
      "aliases": ["换元法", "变量替换"],
      "description": "通过变量替换将被积函数化为基本积分公式的方法。"
    },
    {
      "canonical_name": "分部积分法",
      "aliases": ["分部积分"],
      "description": "利用导数的乘积法则反推的不定积分方法。"
    },
    {
      "canonical_name": "定积分",
      "aliases": ["黎曼积分", "定积分定义"],
      "description": "函数在闭区间上黎曼和的极限，表示曲边梯形面积。"
    },
    {
      "canonical_name": "牛顿-莱布尼茨公式",
      "aliases": ["微积分基本定理", "N-L公式"],
      "description": "将定积分与不定积分联系起来，通过原函数计算定积分。"
    },
    {
      "canonical_name": "定积分应用",
      "aliases": ["积分应用", "面积", "体积"],
      "description": "利用定积分计算面积、体积、弧长等几何量。"
    }
  ],
