    {"from": "导数", "to": "罗尔定理"},
    {"from": "罗尔定理", "to": "拉格朗日中值定理"},
    {"from": "拉格朗日中值定理", "to": "柯西中值定理"},
    {"from": "柯西中值定理", "to": "洛必达法则"},
    {"from": "导数", "to": "泰勒公式"},
    {"from": "拉格朗日中值定理", "to": "泰勒公式"},
    {"from": "导数", "to": "不定积分"},
    {"from": "不定积分", "to": "换元积分法"},
